const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: 'F' },
      { kind: 'text', payload: '拉力（向上）' },
      { kind: 'text', payload: '瓶内气压与摩擦的合力' },
      { kind: 'text', payload: '（方向向下）' },
      { kind: 'text', payload: '木塞' }
    ];
  },
  render: function (input, metrics) {
    var S = visualSdk;
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var cx = W * 0.5;

    var halfNeck = Math.min(W * 0.09, H * 0.11);
    var halfBody = halfNeck * 2.0;
    var neckTop = H * 0.22;
    var neckBot = H * 0.50;
    var shoulderBot = H * 0.64;
    var bodyBot = H * 0.90;

    var bottle = S.polyline([
      [cx - halfNeck, neckTop],
      [cx - halfNeck, neckBot],
      [cx - halfBody, shoulderBot],
      [cx - halfBody, bodyBot],
      [cx + halfBody, bodyBot],
      [cx + halfBody, shoulderBot],
      [cx + halfNeck, neckBot],
      [cx + halfNeck, neckTop]
    ]);

    var halfCork = halfNeck * 0.8;
    var corkTop = neckTop - H * 0.02;
    var corkBot = neckTop + H * 0.16;
    var cork = S.polyline([
      [cx - halfCork, corkTop],
      [cx + halfCork, corkTop],
      [cx + halfCork, corkBot],
      [cx - halfCork, corkBot],
      [cx - halfCork, corkTop]
    ]);

    var fTipY = corkTop - H * 0.15;
    var arrowF = S.arrow(cx, corkTop, cx, fTipY, {});

    var dTipY = corkBot + H * 0.24;
    var arrowD = S.arrow(cx, corkBot, cx, dTipY, {});

    var upMidY = (corkTop + fTipY) / 2;
    var corkMidY = (corkTop + corkBot) / 2;

    return {
      schemaVersion: 1,
      sceneId: 'cork-force-diagram',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: [
        { id: 'bottle', commands: bottle },
        { id: 'cork', commands: cork },
        { id: 'forceUp', commands: arrowF },
        { id: 'forceDown', commands: arrowD }
      ],
      root: {
        type: 'group',
        children: [
          { type: 'path', pathId: 'bottle', fill: '#f4f8fb', stroke: { width: 3, color: '#2b3d52' } },
          { type: 'path', pathId: 'cork', fill: '#d8a86a', stroke: { width: 2, color: '#8a5a2b' } },
          { type: 'path', pathId: 'forceUp', fill: '#c0392b', stroke: { width: 3, color: '#c0392b' } },
          { type: 'path', pathId: 'forceDown', fill: '#1f5f8b', stroke: { width: 3, color: '#1f5f8b' } },
          { type: 'label', contentId: 'c0', anchor: { x: cx + 14, y: upMidY }, hAlign: 'left', vAlign: 'middle', color: '#c0392b' },
          { type: 'label', contentId: 'c1', anchor: { x: cx + 14, y: upMidY + 18 }, hAlign: 'left', vAlign: 'top', color: '#c0392b' },
          { type: 'label', contentId: 'c2', anchor: { x: cx, y: dTipY + 10 }, hAlign: 'center', vAlign: 'top', color: '#1f5f8b' },
          { type: 'label', contentId: 'c3', anchor: { x: cx, y: dTipY + 34 }, hAlign: 'center', vAlign: 'top', color: '#1f5f8b' },
          { type: 'label', contentId: 'c4', anchor: { x: cx - halfNeck - 10, y: corkMidY }, hAlign: 'right', vAlign: 'middle', color: '#8a5a2b' }
        ]
      }
    };
  }
};
